; rdy_x_mr: READY left low, then a byte read under field 3
; Generated by validation/v35s/ready.py emit: the bytes are the generator's; the image
; also holds wtc.py's fill, sleds and stubs (base_image). READY holds (register 0Ah) run: 0; x_half [2]
    DB 0FAh    ; DI
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 8Eh, 0D0h    ; MOV SS, AW
    DB 0BCh, 00h, 0Fh    ; MOV SP, 0F00h
    DB 8Eh, 0D8h    ; MOV DS0, AW
    DB 0B8h, 00h, 0F0h    ; MOV AW, F000h
    DB 8Eh, 0C0h    ; MOV DS1, AW
    DB 26h, 0C6h, 06h, 0E1h, 0FFh, 0ECh    ; MOV byte DS1:[FFE1h], ECh
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 08h, 80h    ; MOV word DS1:[FFE8h], 8008h
    DB 0BAh, 10h, 0FFh    ; MOV DW, FF10h
    DB 0B8h, 41h, 00h    ; MOV AW, 0041h
    DB 0EFh    ; OUT DW, AW
    DB 26h, 0C6h, 06h, 00h, 0FFh, 55h    ; MOV byte DS1:[FF00h], 55h
    DB 26h, 0C6h, 06h, 01h, 0FFh, 00h    ; MOV byte DS1:[FF01h], 00h
    DB 26h, 0C6h, 06h, 02h, 0FFh, 80h    ; MOV byte DS1:[FF02h], 80h
    DB 26h, 0C6h, 06h, 08h, 0FFh, 00h    ; MOV byte DS1:[FF08h], 00h
    DB 26h, 0C6h, 06h, 09h, 0FFh, 6Fh    ; MOV byte DS1:[FF09h], 6Fh
    DB 0BAh, 10h, 0FFh    ; MOV DW, FF10h
    DB 0B8h, 82h, 00h    ; MOV AW, 0082h
    DB 0EFh    ; OUT DW, AW
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 26h, 0C6h, 06h, 0Ah, 0FFh, 80h    ; MOV byte DS1:[FF0Ah], 80h
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 26h, 0A0h, 08h, 0FFh    ; MOV AL, DS1:[FF08h]   ; P1 as the CPU reads it
    DB 0A2h, 10h, 0Fh    ; MOV [0F10h], AL
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 0EFh    ; OUT DW, AW
    DB 26h, 0A0h, 40h, 0FEh    ; MOV AL, DS1:[FE40h]   ; internal RAM
    DB 26h, 0A2h, 41h, 0FEh    ; MOV DS1:[FE41h], AL   ; internal RAM
    DB 26h, 0A1h, 0E8h, 0FFh    ; MOV AW, DS1:[FFE8h]   ; WTC
    DB 26h, 0A0h, 0FFh, 0FFh    ; MOV AL, DS1:[FFFFh]   ; IDB
    DB 26h, 0A2h, 82h, 0FFh    ; MOV DS1:[FF82h], AL   ; MD0 (an SFR store)
    DB 0B8h, 00h, 20h    ; MOV AW, 2000h
    DB 8Eh, 0D8h    ; MOV DS0, AW
    DB 0A0h, 00h, 01h    ; MOV AL, [0100h]   ; 20100
    DB 0A2h, 30h, 01h    ; MOV [0130h], AL   ; 20130
    DB 0A1h, 05h, 01h    ; MOV AW, [0105h]   ; 20105
    DB 0A3h, 35h, 01h    ; MOV [0135h], AW   ; 20135
    DB 0BAh, 40h, 00h    ; MOV DW, 0040h
    DB 0ECh    ; IN AL, DW   ; 0040
    DB 0EEh    ; OUT DW, AL   ; 0040
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 8Eh, 0D8h    ; MOV DS0, AW
    DB 0BAh, 12h, 0FFh    ; MOV DW, FF12h
    DB 0B8h, 01h, 00h    ; MOV AW, 0001h
    DB 0EFh    ; OUT DW, AW
    DB 0F4h    ; HALT
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
cont:
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 0EFh    ; OUT DW, AW
    DB 26h, 0A0h, 08h, 0FFh    ; MOV AL, DS1:[FF08h]   ; P1 again
    DB 0A2h, 12h, 0Fh    ; MOV [0F12h], AL
    DB 0BAh, 40h, 0FEh    ; MOV DW, FE40h
    DB 0B8h, 01h, 00h    ; MOV AW, 0001h
    DB 0EFh    ; OUT DW, AW
    DB 0B8h, 00h, 20h    ; MOV AW, 2000h
    DB 8Eh, 0D8h    ; MOV DS0, AW
    DB 0BAh, 40h, 00h    ; MOV DW, 0040h
