    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 0Ch, 0C0h    ; MOV word DS1:[FFE8h], C00Ch
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 0A0h, 00h, 02h    ; MOV AL, [0200h]   ; 20200
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 90h    ; NOP
    DB 26h, 0C7h, 06h, 0E8h, 0FFh, 08h, 80h    ; MOV word DS1:[FFE8h], 8008h
    DB 0B8h, 00h, 00h    ; MOV AW, 0000h
    DB 8Eh, 0D8h    ; MOV DS0, AW
    DB 0BAh, 42h, 0FEh    ; MOV DW, FE42h
    DB 0B8h, 01h, 00h    ; MOV AW, 0001h
    DB 0EFh    ; OUT DW, AW
    DB 0BAh, 00h, 0FFh    ; MOV DW, FF00h
    DB 0EEh    ; OUT DW, AL
    DB 0F4h    ; HALT
done:
    DB 0EBh, 0FEh    ; BR done
nmi:
    DB 0BAh, 44h, 0FEh    ; MOV DW, FE44h
    DB 0B8h, 4Eh, 00h    ; MOV AW, 004Eh
    DB 0EFh    ; OUT DW, AW
    DB 83h, 0C4h, 06h    ; ADD SP, 6
    DB 0E9h, 97h, 0FFh    ; BR cont
